//! Differential-matrix driver: run the engine over tests/matrix.tsv and
//! emit, per row, the matches the way `grep -o` prints them (non-empty
//! matches only, one per line). Byte-compare the output against the GNU
//! grep run of the same table (see tests/matrix_expected.txt, generated by
//! target/regex-probe/gnu_matrix.sh under WSL).
//!
//! Usage: matrix_harness <matrix.tsv> [> out.txt]

use std::io::Write;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let path = args.get(1).expect("usage: matrix_harness <matrix.tsv>");
    let tsv = std::fs::read(path).expect("read tsv");
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    for (idx, line) in tsv.split(|b| *b == b'\n').enumerate() {
        if line.is_empty() {
            continue;
        }
        let parts: Vec<&[u8]> = line.split(|b| *b == b'\t').collect();
        if parts.len() != 3 {
            panic!("row {} malformed: {} fields", idx, parts.len());
        }
        let syntax = match parts[0] {
            b"BRE" => winux_regex::Syntax::Basic,
            b"ERE" => winux_regex::Syntax::Extended,
            other => panic!(
                "row {} unknown syntax {:?}",
                idx,
                String::from_utf8_lossy(other)
            ),
        };
        let pattern = parts[1];
        let text = parts[2];
        writeln!(out, "##ROW {}", idx).expect("write");
        // GNU grep prints nothing for a compile error; so do we (the
        // accept/reject boundary is pinned by tests/parser_accept.rs).
        let Ok(re) = winux_regex::Regex::compile_bytes(syntax, pattern) else {
            continue;
        };
        // grep -o emulation: suppress empty matches, advance one byte past
        // them (GNU-verified: 'b*' over "ab" prints just "b").
        let mut cursor = 0usize;
        while cursor <= text.len() {
            let Some(m) = re.find_at_bytes(text, cursor) else {
                break;
            };
            if m.end > m.begin {
                let _ = out.write_all(m.slice_of(text));
                let _ = out.write_all(b"\n");
            }
            cursor = if m.end > m.begin { m.end } else { m.begin + 1 };
        }
    }
}
